// Adobe's rerun6 static-UI cases (fresh/ui6.mjs), copied unchanged. Labels are Adobe's.
const R = (body) => `import { useState } from "react";\nimport { photoshop } from "./globals";\n${body}`;
export const UI6_CASES = [
 ["U1 const-false guard", "reject", "src/main.tsx", R(`const SHOW = false;\nexport function P(){ const [error, setError] = useState(""); const go = async () => { try { await photoshop.core.showAlert("x"); } catch (e) { setError(String(e)); } }; return <div><sp-button onClick={go}>Go</sp-button>{SHOW && <sp-body>{error}</sp-body>}</div>; }`)],
 ["U2 unrelated try/catch", "reject", "src/main.tsx", R(`export function P(){ const [error, setError] = useState(""); try { JSON.parse("{}"); } catch (e) { setError(String(e)); } const go = () => photoshop.core.showAlert("x"); return <div><sp-button onClick={go}>Go</sp-button><sp-body>{error}</sp-body></div>; }`)],
 ["U3 hidden attribute", "reject", "src/main.tsx", R(`export function P(){ const [error, setError] = useState(""); const go = async () => { try { await photoshop.core.showAlert("x"); } catch (e) { setError(String(e)); } }; return <div><sp-button onClick={go}>Go</sp-button><sp-body hidden>{error}</sp-body></div>; }`)],
 ["U4 disabled={busy && false}", "reject", "src/main.tsx", R(`export function P(){ const [busy, setBusy] = useState(false); const go = async () => { setBusy(true); await photoshop.core.showAlert("x"); setBusy(false); }; return <sp-button disabled={busy && false} onClick={go}>Go</sp-button>; }`)],
 ["U5 error component never mounted", "reject", "src/main.tsx", R(`export function P(){ const [error, setError] = useState(""); const go = async () => { try { await photoshop.core.showAlert("x"); } catch (e) { setError(String(e)); } }; function ErrorLine(){ return <sp-body>{error}</sp-body>; } return <sp-button onClick={go}>Go</sp-button>; }`)],
 ["U6 set then cleared in catch", "reject", "src/main.tsx", R(`export function P(){ const [error, setError] = useState(""); const go = async () => { try { await photoshop.core.showAlert("x"); } catch (e) { setError(String(e)); setError(""); } }; return <div><sp-button onClick={go}>Go</sp-button><sp-body>{error}</sp-body></div>; }`)],
 ["U7 Vue v-show=false", "reject", "src/main.vue", `<script setup lang="ts">\nimport { ref } from "vue";\nimport { photoshop } from "./globals";\nconst error = ref("");\nasync function go(){ try { await photoshop.core.showAlert("x"); } catch (e) { error.value = String(e); } }\n</script>\n<template><sp-button @click="go">Go</sp-button><sp-body v-show="false">{{ error }}</sp-body></template>\n`],
 ["U8 Svelte {#if 0 > 1}", "reject", "src/main.svelte", `<script lang="ts">\nimport { photoshop } from "./globals";\nlet error = "";\nasync function go(){ try { await photoshop.core.showAlert("x"); } catch (e) { error = String(e); } }\n</script>\n<sp-button on:click={go}>Go</sp-button>\n{#if 0 > 1}<sp-body>{error}</sp-body>{/if}\n`],
 ["U9 style display none", "reject", "src/main.tsx", R(`export function P(){ const [error, setError] = useState(""); const go = async () => { try { await photoshop.core.showAlert("x"); } catch (e) { setError(String(e)); } }; return <div><sp-button onClick={go}>Go</sp-button><sp-body style={{ display: "none" }}>{error}</sp-body></div>; }`)],
 ["U10 rendered as key only", "reject", "src/main.tsx", R(`export function P(){ const [error, setError] = useState(""); const go = async () => { try { await photoshop.core.showAlert("x"); } catch (e) { setError(String(e)); } }; return <div key={error}><sp-button onClick={go}>Go</sp-button><sp-body>Ready</sp-body></div>; }`)],
 ["U11 Vue v-if on const false", "reject", "src/main.vue", `<script setup lang="ts">\nimport { ref } from "vue";\nimport { photoshop } from "./globals";\nconst error = ref("");\nconst show = false;\nasync function go(){ try { await photoshop.core.showAlert("x"); } catch (e) { error.value = String(e); } }\n</script>\n<template><sp-button @click="go">Go</sp-button><sp-body v-if="show">{{ error }}</sp-body></template>\n`],
 ["U12 busy toggled but never rendered", "reject", "src/main.tsx", R(`export function P(){ const [busy, setBusy] = useState(false); const go = async () => { setBusy(true); await photoshop.core.showAlert("x"); setBusy(false); }; return <sp-button onClick={go}>{busy ? "Go" : "Go"}</sp-button>; }`)],
 ["V1 React .catch error", "pass", "src/main.tsx", R(`export function P(){ const [error, setError] = useState(""); const go = () => { photoshop.core.showAlert("x").catch((e) => setError(String(e))); }; return <div><sp-button onClick={go}>Go</sp-button>{error && <sp-body>{error}</sp-body>}</div>; }`)],
 ["V2 React busy finally", "pass", "src/main.tsx", R(`export function P(){ const [busy, setBusy] = useState(false); const go = async () => { setBusy(true); try { await photoshop.core.showAlert("x"); } finally { setBusy(false); } }; return <sp-button disabled={busy} onClick={go}>Go</sp-button>; }`)],
 ["V3 useReducer error", "pass", "src/main.tsx", `import { useReducer } from "react";\nimport { photoshop } from "./globals";\nfunction reduce(s: any, a: any){ return { ...s, error: a.error }; }\nexport function P(){ const [state, dispatch] = useReducer(reduce, { error: "" }); const go = async () => { try { await photoshop.core.showAlert("x"); } catch (e) { dispatch({ error: String(e) }); } }; return <div><sp-button onClick={go}>Go</sp-button><sp-body>{state.error}</sp-body></div>; }`],
 ["V4 Vue error ref", "pass", "src/main.vue", `<script setup lang="ts">\nimport { ref } from "vue";\nimport { photoshop } from "./globals";\nconst error = ref("");\nasync function go(){ try { await photoshop.core.showAlert("x"); } catch (e) { error.value = String(e); } }\n</script>\n<template><sp-button @click="go">Go</sp-button><sp-body v-if="error">{{ error }}</sp-body></template>\n`],
 ["V5 Svelte busy disabled", "pass", "src/main.svelte", `<script lang="ts">\nimport { photoshop } from "./globals";\nlet busy = false;\nasync function go(){ busy = true; try { await photoshop.core.showAlert("x"); } finally { busy = false; } }\n</script>\n<sp-button disabled={busy} on:click={go}>Go</sp-button>\n`],
 ["V6 React custom hook error", "pass", "src/main.tsx", R(`function useAction(){ const [error, setError] = useState(""); const run = async () => { try { await photoshop.core.showAlert("x"); } catch (e) { setError(String(e)); } }; return { error, run }; }\nexport function P(){ const { error, run } = useAction(); return <div><sp-button onClick={run}>Go</sp-button><sp-body>{error}</sp-body></div>; }`)],
 ["V7 Svelte store error", "pass", "src/main.svelte", `<script lang="ts">\nimport { writable } from "svelte/store";\nimport { photoshop } from "./globals";\nconst error = writable("");\nasync function go(){ try { await photoshop.core.showAlert("x"); } catch (e) { error.set(String(e)); } }\n</script>\n<sp-button on:click={go}>Go</sp-button>\n{#if $error}<sp-body>{$error}</sp-body>{/if}\n`],
 ["V8 Vue reactive object error", "pass", "src/main.vue", `<script setup lang="ts">\nimport { reactive } from "vue";\nimport { photoshop } from "./globals";\nconst state = reactive({ error: "" });\nasync function go(){ try { await photoshop.core.showAlert("x"); } catch (e) { state.error = String(e); } }\n</script>\n<template><sp-button @click="go">Go</sp-button><sp-body>{{ state.error }}</sp-body></template>\n`],
 ["V9 React then rejection handler", "pass", "src/main.tsx", R(`export function P(){ const [error, setError] = useState(""); const go = () => { photoshop.core.showAlert("x").then(() => setError(""), (e) => setError(String(e))); }; return <div><sp-button onClick={go}>Go</sp-button><sp-body>{error}</sp-body></div>; }`)],
 ["V10 React loading conditional", "pass", "src/main.tsx", R(`export function P(){ const [loading, setLoading] = useState(false); const go = async () => { setLoading(true); await photoshop.core.showAlert("x"); setLoading(false); }; return <div><sp-button onClick={go}>Go</sp-button>{loading ? <sp-body>Working…</sp-body> : null}</div>; }`)],
];
